import { useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useQuery } from '@tanstack/react-query';
import { BlockedIcon, Logo, OkIcon, WaitingIcon } from '../components';
import type { RepositoriesView, TodayView } from '../../shared/views';

async function get<T>(path: string): Promise<T> {
  const res = await fetch(path, { headers: { accept: 'application/json' }, credentials: 'same-origin' });
  if (!res.ok) throw new Error(String(res.status));
  return res.json() as Promise<T>;
}

/** The preview card shows the sample dashboard, generated by the same rules as the app. */
function Preview() {
  const today = useQuery({ queryKey: ['landing', 'today'], queryFn: () => get<TodayView>('/api/sample/today') });
  const repos = useQuery({ queryKey: ['landing', 'repos'], queryFn: () => get<RepositoriesView>('/api/sample/repositories') });
  if (!today.data || !repos.data) return <div className="card-lg preview" style={{ minHeight: 360 }} aria-hidden="true" />;
  return (
    <div className="card-lg preview" aria-label="A sample of the Today screen">
      <span style={{ fontSize: 13, color: 'var(--color-muted)' }}>Today · {today.data.date_line} · sample</span>
      <span style={{ fontSize: 26, fontWeight: 700, letterSpacing: '-0.02em', lineHeight: 1.15 }}>{today.data.headline}</span>
      <div style={{ display: 'flex', flexDirection: 'column' }}>
        {repos.data.rows.map((r) => (
          <div key={r.full_name} className="preview-row">
            {r.tone === 'blocked' ? <BlockedIcon size={18} /> : <OkIcon size={18} />}
            <span style={{ display: 'flex', flexDirection: 'column', flex: 1, minWidth: 0 }}>
              <span style={{ fontSize: 16, fontWeight: 600 }}>{r.name}</span>
              {r.reason_tone === 'blocked' && <span style={{ fontSize: 14, color: 'var(--color-muted)' }}>{r.reason}</span>}
            </span>
            {r.reason_tone === 'blocked'
              ? <span className="pill pill-blocked pill-small">Blocked</span>
              : <span className="tone-ok" style={{ fontSize: 13, fontWeight: 600 }}>On track</span>}
          </div>
        ))}
      </div>
    </div>
  );
}

